Create Lab Order.code:
// Create a lab order: patient + sample + ordered tests.
// Paths are relative to /api/OpenELIS-Global/rest/ on the configured baseUrl.
http.post('SamplePatientEntry', {
  patientProperties: {
    // ADD a new patient, or UPDATE / NO_ACTION for an existing one.
    patientUpdateStatus: 'ADD',
    firstName: $.data.patient.firstName,
    lastName: $.data.patient.lastName,
    gender: $.data.patient.gender, // 'M' or 'F'
    birthDateForDisplay: $.data.patient.birthDate, // dd/MM/yyyy
    nationalId: $.data.patient.nationalId,
  },
  sampleOrderItems: {
    labNo: $.data.labNumber, // accession number
    receivedDateForDisplay: $.data.receivedDate, // dd/MM/yyyy
    requesterSampleID: $.data.externalOrderId, // the EMR's order id
    priority: 'ROUTINE',
  },
  // XML describing the sample type and ordered tests/panels.
  sampleXML: $.data.sampleXML,
});

Create or Update Patient.code:
// Create (or update) a patient record.
http.post('PatientManagement', {
  // ADD for a new patient; UPDATE with patientPK for an existing one.
  patientUpdateStatus: 'ADD',
  firstName: $.data.firstName,
  lastName: $.data.lastName,
  gender: $.data.sex, // 'M' or 'F'
  birthDateForDisplay: $.data.dateOfBirth, // dd/MM/yyyy
  nationalId: $.data.nationalId,
  primaryPhone: $.data.phone,
  city: $.data.district,
});

Save Test Results.code:
// Save results for tests awaiting entry.
http.post('LogbookResults', {
  accessionNumber: $.data.labNumber,
  testSectionId: $.data.testSectionId,
  testResult: [
    {
      accessionNumber: $.data.labNumber,
      analysisId: $.data.analysisId, // from a GET LogbookResults lookup
      testId: $.data.testId,
      resultValue: $.data.value, // e.g. '13.5'
      resultType: 'N', // numeric
      unitsOfMeasure: 'g/dL',
      note: 'Imported from analyzer middleware',
    },
  ],
});

Get Results For Accession.code:
// Get the results for a lab order by its accession number.
http.get('accession-results', {
  query: { accessionNumber: $.data.labNumber },
});

Search Patients.code:
// Search patients (paged results).
http.get('patient-search-results', {
  query: {
    nationalID: $.data.nationalId,
    // Other filters: firstName, lastName, labNumber, dateOfBirth, gender
    page: 1,
  },
});

Find Order By Lab Number.code:
// Find an order by its lab / accession number.
http.get('order/search', {
  query: { labNumber: $.data.labNumber },
});

Get Patient By Lab Number.code:
// Get the patient for an accession number.
http.get('patientByLabNumer', {
  query: { accessionNumber: $.data.labNumber },
});

List Results Awaiting Validation.code:
// List results awaiting validation for a test section.
http.get('AccessionValidation', {
  query: { testSectionId: $.data.testSectionId },
});

Query FHIR Resources.code:
// Query FHIR resources of one type via the OpenELIS passthrough.
http.get('fhir/DiagnosticReport', {
  query: {
    count: 50, // page size
    includeTotal: true,
  },
});
